public void testExistsNotNull_1_oe() throws FileSystemException {
    boolean a = FileObjectUtils.exists(VFS.getManager().toFileObject(SystemUtils.getJavaIoTmpDir()));
    Assert.assertTrue(a);
}

@Test
public void testgetContentAsString_Charset_1_oe() throws FileSystemException, IOException {
    Object a = FileObjectUtils.getContentAsString(VFS.getManager().toFileObject(new File("src/test/resources/test-data/read-tests/file1.txt")),StandardCharsets.UTF_8);
    Assert.assertEquals("This is a test file.", a);
}

@Test
public void testgetContentAsString_CharsetNull_1_oe() throws FileSystemException, IOException {
    Object a = FileObjectUtils.getContentAsString(VFS.getManager().toFileObject(new File("src/test/resources/test-data/read-tests/file1.txt")),(Charset)null);
    Assert.assertEquals("This is a test file.", a);
}

@Test
public void testgetContentAsString_String_1_oe() throws FileSystemException, IOException {
    Object a = FileObjectUtils.getContentAsString(VFS.getManager().toFileObject(new File("src/test/resources/test-data/read-tests/file1.txt")),"UTF-8");
    Assert.assertEquals("This is a test file.", a);
}

@Test
public void testgetContentAsString_StringNull_1_oe() throws FileSystemException, IOException {
    Object a = FileObjectUtils.getContentAsString(VFS.getManager().toFileObject(new File("src/test/resources/test-data/read-tests/file1.txt")),(String)null);
    Assert.assertEquals("This is a test file.", a);
}

@Test
public void testNotExistsNotNull_1_oe() throws FileSystemException {
    boolean a = FileObjectUtils.exists(VFS.getManager().toFileObject(new File("This file can't possibly exist,right?")));
    Assert.assertFalse(a);
}

@Test
public void testNotExistsNull_1_oe() throws FileSystemException {
    boolean a = FileObjectUtils.exists(null);
    Assert.assertFalse(a);
}

mut_method_definition:
public static boolean exists(final FileObject fileObject) throws FileSystemException {
        return fileObject != null && fileObject.exists();
    }
